def _cycle_zoom(timing, imgdir, memes, spec):
    cyc = spec['ZOOM_CYCLE']
    out, prev, ci = ([], None, 0)
    for g in timing['groups']:
        i = g['i']
        is_meme = i in memes
        src = memes[i] if is_meme else f"{imgdir}/{int(g['img']):02d}.png"
        if src == prev:
            here = cyc[ci % len(cyc)]
            ci += max(range(1, len(cyc)), key=lambda off: (abs(cyc[(ci + off) % len(cyc)] - here), -off))
        else:
            ci += 1
        zoom = cyc[ci % len(cyc)]
        pair = g.get('pair')
        if pair == 'wide':
            zoom = spec['PAIR_WIDE']
        if pair == 'close':
            zoom = spec['PAIR_CLOSE']
        if g['color'] == 'RED' or is_meme:
            zoom = max(zoom, spec['WIGGLE_MIN_ZOOM'])
        out.append({'i': i, 'src': src, 'zoom': zoom, 'is_meme': is_meme, 'wiggle': g['color'] == 'RED' or is_meme, 'd': g['d'], 't': g['t']})
        prev = src
    return out

def _wiggle_frames(dur, spec):
    step = 1.0 / spec['FPS']
    out, t_used = ([], 0.0)
    while t_used < dur - 1e-06:
        d = min(step, dur - t_used)
        out.append((t_used, d))
        t_used += d
    return out

def _wiggle_offset(t_used, spec):
    w = 2 * math.pi * spec['WIGGLE_HZ']
    z = 1.0 + spec['WIGGLE_AMP'] * math.sin(t_used * w)
    dx = spec['WIGGLE_DX'] * math.sin(t_used * w * 0.83)
    dy = spec['WIGGLE_DY'] * math.sin(t_used * w + 1.1)
    return (z, dx, dy)

def _slot_box(sw, sh, cx, cy, zoom, spec, pan=None, off=(0.0, 0.0)):
    SW, SH = (spec['SLOT_W'], spec['SLOT_H'])
    r = max(SW / sw, SH / sh) * zoom
    nw, nh = (max(int(sw * r + 0.5), SW), max(int(sh * r + 0.5), SH))
    if pan is None:
        left = int(cx * nw - SW / 2)
    else:
        left = int((nw - SW) * pan)
    top = int(cy * nh - SH / 2)
    left += int(off[0])
    top += int(off[1])
    left = max(0, min(left, max(nw - SW, 0)))
    top = max(0, min(top, max(nh - SH, 0)))
    return {'resize': [nw, nh], 'crop': [left, top, left + SW, top + SH]}

