def _meme_box(geom, zoom, spec, off=(0.0, 0.0)):
    SW, SH = (spec['SLOT_W'], spec['SLOT_H'])
    W0, H0 = (geom['w'], geom['h'])
    fh, bw = (geom['fh'], geom['bw'])
    cx, cy = (geom['cx'], geom['cy'])
    r = SH * (0.86 if geom['full_body'] else 0.98) / fh * zoom
    r = max(r, SW * 0.98 / bw)
    r = max(r, SW / W0, SH / H0)
    nw, nh = (max(int(W0 * r + 0.5), SW), max(int(H0 * r + 0.5), SH))
    left = int(cx * r - SW / 2) + int(off[0])
    top = int(cy * r - SH / 2) + int(off[1])
    left = max(0, min(left, nw - SW))
    top = max(0, min(top, nh - SH))
    return {'resize': [nw, nh], 'crop': [left, top, left + SW, top + SH]}

def build_parts(timing, imgdir, memes, images, meme_geom, spec, *, text_review=None):
    card_src = f"{imgdir}/{int(timing.get('card_img', 24)):02d}.png"
    parts = []
    pan_n = max(int(timing['card_end'] * 12), 2)
    ci = images.get(card_src)
    if ci is None:
        raise KeyError(card_src)
    for k in range(pan_n):
        pan = 0.35 + 0.3 * (k / max(pan_n - 1, 1))
        box = _image_box(ci, spec['INTRO_ZOOM'], spec, pan=pan, usage='intro', text_review=text_review)
        parts.append({'dst': f'slot/intro_{k:02d}.jpg', 'dur': timing['card_end'] / pan_n, 'src': card_src, **box})
    for g in _cycle_zoom(timing, imgdir, memes, spec):
        src = g['src']
        if g['is_meme'] and (not ((images.get(src) or {}).get('focus_measurement') or (images.get(src) or {}).get('focus_by_usage'))):
            geom = meme_geom.get(src.split('/')[-1])
            if geom is None:
                raise KeyError(src)
            box_of = lambda off=(0.0, 0.0), z=g['zoom']: _meme_box(geom, z, spec, off)
        else:
            im = images.get(src)
            if im is None:
                raise KeyError(src)
            box_of = lambda off=(0.0, 0.0), z=g['zoom']: _image_box(im, z, spec, off=off, usage=f"group:{g['i']}", text_review=text_review)
        if g['wiggle']:
            for k, (t_used, d) in enumerate(_wiggle_frames(g['d'], spec)):
                z, dx, dy = _wiggle_offset(t_used, spec)
                parts.append({'dst': f"slot/w{g['i']:02d}_{k:02d}.jpg", 'dur': d, 'src': src, **box_of(off=(dx, dy), z=g['zoom'] * z)})
        else:
            parts.append({'dst': f"slot/g{g['i']:02d}.jpg", 'dur': g['d'], 'src': src, **box_of()})
    return parts

def concat_entry(workdir, p):
    p = str(p)
    if not (p.startswith('/') or (len(p) > 2 and p[1] == ':' and (p[2] in '/\\'))):
        p = workdir.rstrip('/') + '/' + p
    return "file '" + p.replace("'", "'\\''") + "'"

def vconcat_text(parts, workdir, fps=None):
    if fps:
        eps = 0.0001
        cum, n_prev, acc, v = (0.0, 0, 0.0, [])
        for p in parts:
            cum += float(p['dur'])
            n = max(int(round(cum * float(fps))), n_prev + 1)
            d = n / float(fps) + eps - acc
            v += [concat_entry(workdir, p['dst']), f'duration {d:.6f}']
            acc += round(d, 6)
            n_prev = n
        v.append(concat_entry(workdir, parts[-1]['dst']))
        return '\n'.join(v) + '\n'
    wd = workdir.rstrip('/')
    lines = ['ffconcat version 1.0']
    for p in parts:
        lines.append(concat_entry(wd, p['dst']))
        lines.append(f"duration {p['dur']:.4f}")
    lines.append(concat_entry(wd, parts[-1]['dst']))
    return '\n'.join(lines) + '\n'

def slot_box_f(sw, sh, cx, cy, zoom, spec, pan=None, off=(0.0, 0.0)):
    SW, SH = (spec['SLOT_W'], spec['SLOT_H'])
    r = max(SW / sw, SH / sh) * float(zoom)
    nw, nh = (sw * r, sh * r)
    left = (nw - SW) * float(pan) if pan is not None else cx * nw - SW / 2.0
    top = cy * nh - SH / 2.0
    left += float(off[0])
    top += float(off[1])
    left = max(0.0, min(left, max(nw - SW, 0.0)))
    top = max(0.0, min(top, max(nh - SH, 0.0)))
    bw, bh = (SW / r, SH / r)
    x0 = max(0.0, min(left / r, max(sw - bw, 0.0)))
    y0 = max(0.0, min(top / r, max(sh - bh, 0.0)))
    return {'resize': [max(int(nw + 0.5), SW), max(int(nh + 0.5), SH)], 'crop': [int(left), int(top), int(left) + SW, int(top) + SH], 'srcbox': [x0, y0, min(x0 + bw, float(sw)), min(y0 + bh, float(sh))], 'dst_size': [SW, SH]}

def _cut_zoom(timing, imgdir, memes, spec):
    cyc = spec['ZOOM_CYCLE']
    out, prev, ci = ([], None, 0)
    for g in timing['groups']:
        i = g['i']
        is_meme = i in memes
        src = memes[i] if is_meme else f"{imgdir}/{int(g['img']):02d}.png"
        if src != prev:
            ci += 1
        zoom = cyc[ci % len(cyc)]
        pair = g.get('pair')
        if pair == 'wide':
            zoom = spec['PAIR_WIDE']
        if pair == 'close':
            zoom = spec['PAIR_CLOSE']
        if g['color'] == 'RED' or is_meme:
            zoom = max(zoom, spec['WIGGLE_MIN_ZOOM'])
        out.append({'i': i, 'src': src, 'zoom': zoom, 'is_meme': is_meme, 'wiggle': g['color'] == 'RED' or is_meme, 'd': g['d'], 't': g['t']})
        prev = src
    return out
KB_NEUTRAL = {'WIGGLE_AMP': 0.0, 'WIGGLE_DX': 0.0, 'WIGGLE_DY': 0.0, 'WIGGLE_HZ': 1.0, 'WIGGLE_MIN_ZOOM': 1.0, 'PAIR_WIDE': 1.0, 'PAIR_CLOSE': 1.0}

def black_intro_geometry(spec):
    w, h = (int(spec['SLOT_W']), int(spec['SLOT_H']))
    return {'resize': [w, h], 'crop': [0, 0, w, h]}

def build_parts_kb(timing, imgdir, memes, images, meme_geom, spec, card_bg_image=None, *, text_review=None):
    import hashlib
    fps = float(spec.get('FPS') or 30)
    sp = dict(spec)
    neutral_used = [k for k, v in KB_NEUTRAL.items() if sp.get(k) is None]
    for k in neutral_used:
        sp[k] = KB_NEUTRAL[k]
    card_src = f"{imgdir}/{int(timing.get('card_img', 24)):02d}.png"
    parts = []
    pan_n = max(int(round(float(timing['card_end']) * fps)), 2)
    op = sp.get('OPEN_IMG') or {}
    intro_spec = sp
    if op.get('있나') and op.get('W') and op.get('H'):
        intro_spec = dict(sp, SLOT_W=int(op['W']), SLOT_H=int(op['H']))
    black_box = black_intro_geometry(sp) if card_bg_image is False else None
    ci = images.get(card_src) if black_box is None else None
    if black_box is None and ci is None:
        raise KeyError(card_src)
    Z = float(sp.get('INTRO_ZOOM') or 1.0)
    intro_src = 'black.png' if card_bg_image is False else card_src
    for k in range(pan_n):
        pan = 0.35 + 0.3 * (k / max(pan_n - 1, 1))
        z = 1.0 + (Z - 1.0) * (k / max(pan_n - 1, 1))
        box = black_box if black_box is not None else _image_box(ci, z, intro_spec, pan=pan, usage='intro', text_review=text_review)
        parts.append({'dst': f'slot/intro_{k:02d}.jpg', 'dur': float(timing['card_end']) / pan_n, 'src': intro_src, **box})
    kz = float(sp.get('KB_ZOOM') or 1.0)
    gs = list(_cut_zoom(timing, imgdir, memes, sp))
    runs, st_i = ([], 0)
    for i in range(1, len(gs) + 1):
        if i == len(gs) or gs[i]['src'] != gs[i - 1]['src']:
            runs.append((st_i, i))
            st_i = i
    run_of, run_t0, run_dur = ({}, {}, {})
    for a_i, b_i in runs:
        tot = sum((gs[k]['d'] for k in range(a_i, b_i)))
        acc = 0.0
        for k in range(a_i, b_i):
            run_of[k] = (a_i, b_i)
            run_t0[k] = acc
            run_dur[k] = tot
            acc += gs[k]['d']
    pan_px_s = float(sp.get('KB_PAN_PX_S') or 0)
    zoom_ps = float(sp.get('KB_ZOOM_PER_S') or 0)
    slug = str(timing.get('slug') or '')
    run_idx_of = {a_i: n for n, (a_i, _b) in enumerate(runs)}
    fpct = sp.get('KB_MOVE_FRAME_PCT')
    sel = set()
    if fpct and pan_px_s > 0:
        tot_d = sum((run_dur[a_i] for a_i, _b in runs)) or 1e-06
        order = sorted(runs, key=lambda ab: hashlib.sha256(f'{slug}|kbmove|{run_idx_of[ab[0]]}'.encode()).digest())
        acc = 0.0
        for a_i, _b in order:
            if acc / tot_d >= float(fpct) / 100.0:
                break
            sel.add(run_idx_of[a_i])
            acc += run_dur[a_i]
    sign, prev = (1.0, None)
    for gi, g in enumerate(gs):
        src = g['src']
        if g['is_meme'] and (not ((images.get(src) or {}).get('focus_measurement') or (images.get(src) or {}).get('focus_by_usage'))):
            geom = meme_geom.get(src.split('/')[-1])
            if geom is None:
                raise KeyError(src)
            box_of = lambda off, z, geom=geom: _meme_box(geom, z, sp, off)
        else:
            im = images.get(src)
            if im is None:
                raise KeyError(src)
            box_of = lambda off, z, im=im: _image_box(im, z, sp, off=off, subpixel=True, usage=f"group:{g['i']}", text_review=text_review)
        if src != prev:
            sign = -sign
        prev = src
        if g['wiggle']:
            for k, (t_used, d) in enumerate(_wiggle_frames(g['d'], sp)):
                z, dx, dy = _wiggle_offset(t_used, sp)
                parts.append({'dst': f"slot/w{g['i']:02d}_{k:02d}.jpg", 'dur': d, 'src': src, **box_of((dx, dy), g['zoom'] * z)})
            continue
        ri = run_idx_of.get(run_of[gi][0])
        mv = ri in sel if ri is not None else False
        TD = max(run_dur[gi], 1e-06)
        span = pan_px_s * TD if mv else 0.0
        if not mv:
            parts.append({'dst': f"slot/g{g['i']:02d}.jpg", 'dur': g['d'], 'src': src, **box_of((0.0, 0.0), g['zoom'])})
            continue
        n = max(2, int(round(g['d'] * fps)))
        T0 = run_t0[gi]
        for k in range(n):
            u = (T0 + g['d'] * (k / max(n - 1, 1))) / TD
            z = g['zoom'] * (1.0 + (kz - 1.0) * u + zoom_ps * TD * (u - 0.5))
            dx = sign * span * 0.7071 * (u - 0.5)
            dy = sign * span * 0.7071 * (u - 0.5)
            parts.append({'dst': f"slot/k{g['i']:02d}_{k:03d}.jpg", 'dur': g['d'] / n, 'src': src, **box_of((dx, dy), z)})
    if op.get('있나'):
        for part in parts:
            intro = part['dst'].startswith('slot/intro_')
            xy = [int(op['X0']), int(op['Y0'])] if intro else [int(sp['IMG_X']), int(sp['IMG_Y0'])]
            part['frame_canvas'] = {'size': list(sp['FRAME_CANVAS_SIZE']), 'xy': xy}
            dim = op.get('DIM')
            if intro and dim is not None and (0 < float(dim) < 0.999):
                part['brightness'] = float(dim)
    return parts

def frame_transform(part):
    keys = ('srcbox', 'dst_size') if part.get('srcbox') else ('resize', 'crop')
    return {k: part[k] for k in (*keys, 'order', 'placement', 'brightness', 'frame_canvas', '_photo_usage', '_anchor_clamped') if k in part}

def seq_frames(parts, fps, total):
    n_out = int(round(float(total) * float(fps)))
    edges, acc = ([], 0.0)
    for p in parts:
        acc += float(p['dur'])
        edges.append(int(round(acc * float(fps))))
    out, j = ([], 0)
    for i in range(n_out):
        while j < len(edges) - 1 and i >= edges[j]:
            j += 1
        p = parts[min(j, len(parts) - 1)]
        f = {'src': p['src'], 'dst': f'seq/{i + 1:06d}.jpg'}
        f.update(frame_transform(p))
        out.append(f)
    return out
FRAME_RUN_TOL = 0.002

def pack_frame_runs(frames, dstf='seq/%06d.jpg', tol=FRAME_RUN_TOL, min_run=3, *, frame_guard=None):
    for i, f in enumerate(frames):
        if f.get('dst') != dstf % (i + 1):
            return frames

    def _key(f):
        return (f['src'], 'srcbox' in f, f.get('dst_size'), f.get('order'), f.get('placement'), f.get('brightness'), f.get('frame_canvas'), f.get('_photo_usage'), repr(f.get('_anchor_clamped')))

    def _lerp_ok(a_i, m):
        va = frames[a_i]['srcbox']
        vb = frames[a_i + m - 1]['srcbox']
        for k in range(m):
            t = k / (m - 1) if m > 1 else 0.0
            fv = frames[a_i + k]['srcbox']
            for j in range(4):
                if abs(va[j] + (vb[j] - va[j]) * t - fv[j]) > tol:
                    return False
            if frame_guard is not None and (not frame_guard(frames[a_i + k], [va[j] + (vb[j] - va[j]) * t for j in range(4)])):
                return False
        return True
    segs, st = ([], 0)
    for i in range(1, len(frames) + 1):
        if i == len(frames) or _key(frames[i]) != _key(frames[i - 1]):
            segs.append((st, i))
            st = i
    out = []
    for a, b in segs:
        pos = a
        if 'srcbox' in frames[a]:
            while pos < b:
                hi = 2
                while pos + hi <= b and _lerp_ok(pos, hi):
                    hi *= 2
                hi = min(hi, b - pos)
                best, lo = (1, 1)
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if _lerp_ok(pos, mid):
                        best, lo = (mid, mid + 1)
                    else:
                        hi = mid - 1
                if best >= min_run:
                    f0, f1 = (frames[pos], frames[pos + best - 1])
                    out.append({'run': best, 'src': f0['src'], 'dstf': dstf, 'dst0': pos + 1, 'srcbox0': f0['srcbox'], 'srcbox1': f1['srcbox'], 'dst_size': f0['dst_size'], **{k: f0[k] for k in ('order', 'placement', 'brightness', 'frame_canvas', '_anchor_clamped') if k in f0}})
                else:
                    out.extend(frames[pos:pos + best])
                pos += best
        else:
            while pos < b:
                q, v0 = (pos, frames[pos]['resize'] + frames[pos]['crop'])
                while q < b and frames[q]['resize'] + frames[q]['crop'] == v0:
                    q += 1
                if q - pos >= min_run:
                    out.append({'run': q - pos, 'src': frames[pos]['src'], 'dstf': dstf, 'dst0': pos + 1, 'resize': frames[pos]['resize'], 'crop': frames[pos]['crop'], **{k: frames[pos][k] for k in ('order', 'placement', 'brightness', 'frame_canvas') if k in frames[pos]}})
                else:
                    out.extend(frames[pos:q])
                pos = q
    return out

def expand_frame_runs(frames):
    if not isinstance(frames, list) or not any((isinstance(f, dict) and 'run' in f for f in frames)):
        return frames
    out = []
    for f in frames:
        if not (isinstance(f, dict) and 'run' in f):
            out.append(f)
            continue
        n, d0 = (int(f['run']), int(f['dst0']))
        if 'srcbox0' in f:
            a, b = (f['srcbox0'], f['srcbox1'])
            for k in range(n):
                t = k / (n - 1) if n > 1 else 0.0
                out.append({'src': f['src'], 'dst': f['dstf'] % (d0 + k), 'srcbox': [a[j] + (b[j] - a[j]) * t for j in range(4)], 'dst_size': list(f['dst_size']), **{k: f[k] for k in ('order', 'placement', 'brightness', 'frame_canvas') if k in f}})
        else:
            for k in range(n):
                out.append({'src': f['src'], 'dst': f['dstf'] % (d0 + k), 'resize': list(f['resize']), 'crop': list(f['crop']), **{k: f[k] for k in ('order', 'placement', 'brightness', 'frame_canvas') if k in f}})
    return out

def black_png(w, h):
    import struct
    import zlib

    def chunk(tag, data):
        return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag + data) & 4294967295)
    ihdr = struct.pack('>IIBBBBB', int(w), int(h), 8, 2, 0, 0, 0)
    raw = (b'\x00' + b'\x00' * (3 * int(w))) * int(h)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', ihdr) + chunk(b'IDAT', zlib.compress(raw, 9)) + chunk(b'IEND', b'')

